import{az as e,P as i,Q as s,aQ as a}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const b=JSON.parse('{"title":"我想到一个方案， 就是a.com 和 b.com，  a.com跳转到b.com 时 在url携带sessionid, 让b.com接收并存储cookie， 那么b.com不就是已登录状态了吗","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/浏览器/url跳转携带cookie方案.md","filePath":"面试题/浏览器/url跳转携带cookie方案.md","lastUpdated":1782478366000}'),c={name:"面试题/浏览器/url跳转携带cookie方案.md"};function d(l,o,r,n,t,p){return i(),s("div",null,[...o[0]||(o[0]=[a('<h1 id="我想到一个方案-就是a-com-和-b-com-a-com跳转到b-com-时-在url携带sessionid-让b-com接收并存储cookie-那么b-com不就是已登录状态了吗" tabindex="-1">我想到一个方案， 就是a.com 和 b.com， a.com跳转到b.com 时 在url携带sessionid, 让b.com接收并存储cookie， 那么b.com不就是已登录状态了吗 <a class="header-anchor" href="#我想到一个方案-就是a-com-和-b-com-a-com跳转到b-com-时-在url携带sessionid-让b-com接收并存储cookie-那么b-com不就是已登录状态了吗" aria-label="Permalink to “我想到一个方案， 就是a.com 和 b.com，  a.com跳转到b.com 时 在url携带sessionid, 让b.com接收并存储cookie， 那么b.com不就是已登录状态了吗”">​</a></h1><h2 id="跨域单点登录-session-id-方案的安全风险与优化" tabindex="-1">跨域单点登录：Session ID 方案的安全风险与优化 <a class="header-anchor" href="#跨域单点登录-session-id-方案的安全风险与优化" aria-label="Permalink to “跨域单点登录：Session ID 方案的安全风险与优化”">​</a></h2><p>你的思路在<strong>逻辑上完全成立</strong>，这也是跨域单点登录最原始的雏形方案：Session 的核心只认 sessionId，只要把合法的会话 ID 传递过去、写入目标域名的 Cookie，服务端就能识别到登录状态。</p><p>但必须明确：<strong>这个原生方案有非常严重的安全风险，绝对不能直接在生产环境使用</strong>。下面我拆解清楚它的成立前提、致命问题，以及工业界对应的标准优化方案。</p><h2 id="一、为什么原理上是可行的" tabindex="-1">一、为什么原理上是可行的 <a class="header-anchor" href="#一、为什么原理上是可行的" aria-label="Permalink to “一、为什么原理上是可行的”">​</a></h2><h3 id="核心逻辑" tabindex="-1">核心逻辑 <a class="header-anchor" href="#核心逻辑" aria-label="Permalink to “核心逻辑”">​</a></h3><p>Session 的身份认证只依赖 <code>sessionId</code>：</p><ul><li><p>服务端不关心这个 sessionId 是从 Cookie 里来的，还是 URL 里来的，还是请求头里来的；</p></li><li><p>只要能拿到合法的 sessionId，去共享的 Redis 里查到对应的会话数据，就认定为已登录。</p></li></ul><h3 id="完整流程-你的方案" tabindex="-1">完整流程（你的方案） <a class="header-anchor" href="#完整流程-你的方案" aria-label="Permalink to “完整流程（你的方案）”">​</a></h3><ol><li><p>用户在 <code>a.com</code> 登录成功，获得 sessionId，存在 <code>a.com</code> 的 Cookie 中；</p></li><li><p>用户从 <code>a.com</code> 点击跳转到 <code>b.com</code>，跳转链接带上参数：<code>b.com?sid=xxxxxx</code>；</p></li><li><p><code>b.com</code> 的前端 / 后端拿到 URL 里的 <code>sid</code>，通过 <code>Set-Cookie</code> 把这个 sessionId 写入 <code>b.com</code> 域名下的 Cookie；</p></li><li><p>后续用户访问 <code>b.com</code> 的所有接口，浏览器都会自动携带这个 Cookie；</p></li><li><p>因为 <code>a.com</code> 和 <code>b.com</code> 后端共用同一个 Redis 会话存储，同一个 sessionId 能查到同一份会话数据，因此 <code>b.com</code> 自动处于登录状态。</p></li></ol><h3 id="必须满足的前提" tabindex="-1">必须满足的前提 <a class="header-anchor" href="#必须满足的前提" aria-label="Permalink to “必须满足的前提”">​</a></h3><p>两个域名的后端<strong>必须共享同一份 Session 存储</strong>（同一个 Redis 集群）。如果各自存各自的会话，那 <code>b.com</code> 拿到 sessionId 也查不到数据，仍然是未登录。</p><h2 id="二、原生方案的致命问题" tabindex="-1">二、原生方案的致命问题 <a class="header-anchor" href="#二、原生方案的致命问题" aria-label="Permalink to “二、原生方案的致命问题”">​</a></h2><p>这个方案的所有风险都来自「把长期有效的会话凭证直接暴露在 URL 中」。</p><h3 id="_1-极高的泄露风险-最核心" tabindex="-1">1. 极高的泄露风险（最核心） <a class="header-anchor" href="#_1-极高的泄露风险-最核心" aria-label="Permalink to “1. 极高的泄露风险（最核心）”">​</a></h3><p>sessionId 放在 URL 里，会在多处被留存，一旦泄露，攻击者可以直接冒用身份：</p><ul><li><p>浏览器历史记录、书签、收藏夹里会完整保留带 sessionId 的链接；</p></li><li><p>服务器访问日志、Nginx 日志、CDN 日志都会记录完整 URL，日志泄露即会话泄露；</p></li><li><p>用户分享链接、转发链接时，会把自己的登录凭证一起发出去；</p></li><li><p>跳转过程中，Referer 请求头会把带 sessionId 的 URL 带给第三方站点。</p></li></ul><p>sessionId 通常有效期是几小时到几天，泄露后攻击者可以在有效期内完全冒用账号，危害极大。</p><h3 id="_2-会话固定攻击" tabindex="-1">2. 会话固定攻击 <a class="header-anchor" href="#_2-会话固定攻击" aria-label="Permalink to “2. 会话固定攻击”">​</a></h3><p>攻击者可以主动构造一个链接：<code>b.com?sid=攻击者自己的sessionId</code>，诱导用户点击。</p><ul><li><p>用户点击后，<code>b.com</code> 会把攻击者的会话写入用户的浏览器；</p></li><li><p>如果用户后续在这个会话里登录、绑定敏感信息，攻击者可以直接通过自己的会话拿到用户的所有数据。 这是标准的「会话固定攻击」，原生方案完全没有防御能力。</p></li></ul><h3 id="_3-无法校验来源合法性" tabindex="-1">3. 无法校验来源合法性 <a class="header-anchor" href="#_3-无法校验来源合法性" aria-label="Permalink to “3. 无法校验来源合法性”">​</a></h3><p><code>b.com</code> 收到 sessionId 时，无法确认它真的来自可信的 <code>a.com</code>，任何人都可以随便拼接一个 sid 参数尝试访问。虽然长随机 sessionId 暴力破解概率很低，但缺乏来源校验本身就是安全短板。</p><h3 id="_4-体验与工程缺陷" tabindex="-1">4. 体验与工程缺陷 <a class="header-anchor" href="#_4-体验与工程缺陷" aria-label="Permalink to “4. 体验与工程缺陷”">​</a></h3><ul><li><p>用户直接输入 <code>b.com</code> 访问时，不会携带 sessionId，仍然是未登录，必须从 <code>a.com</code> 跳转才行；</p></li><li><p>过期的 sessionId 留在 URL 里，用户收藏后下次打开会报错；</p></li><li><p>登出后如果用户刷新带参数的页面，又会重新写入失效的 sessionId，逻辑混乱。</p></li></ul><h2 id="三、正确的优化方向-用「一次性授权码」替代-sessionid" tabindex="-1">三、正确的优化方向：用「一次性授权码」替代 sessionId <a class="header-anchor" href="#三、正确的优化方向-用「一次性授权码」替代-sessionid" aria-label="Permalink to “三、正确的优化方向：用「一次性授权码」替代 sessionId”">​</a></h2><p>你的思路本身没有错，只是<strong>不能直接传长期有效的会话凭证</strong>。工业界的标准做法是加一层「临时授权码」中转，这也是 CAS、OAuth2.0 授权码模式的核心原理。</p><h3 id="优化后的安全流程" tabindex="-1">优化后的安全流程 <a class="header-anchor" href="#优化后的安全流程" aria-label="Permalink to “优化后的安全流程”">​</a></h3><ol><li><p><strong>生成授权码</strong>：用户在 <code>a.com</code> 点击跳转到 <code>b.com</code> 时，<code>a.com</code> 后端生成一个<strong>一次性、超短期</strong>的随机授权码 <code>code</code>（比如有效期 5 分钟），存入 Redis 并和对应用户 ID 绑定。</p></li><li><p><strong>跳转传码</strong>：跳转链接只携带这个 code：<code>b.com?code=abc123</code>，不暴露任何真实会话凭证。</p></li><li><p><strong>后端兑换</strong>：<code>b.com</code> 后端拿到 code 后，立刻向 <code>a.com</code> 的校验接口（或直接查共享 Redis）校验 code 的合法性；校验通过，兑换出用户 ID。</p></li><li><p><strong>生成本地会话</strong>：<code>b.com</code> 用兑换到的用户信息，<strong>给自己生成一个独立的 sessionId</strong>，写入 <code>b.com</code> 的 Cookie，同时立即删除 Redis 里的 code（一次性使用）。</p></li></ol><h3 id="为什么这样就安全了" tabindex="-1">为什么这样就安全了 <a class="header-anchor" href="#为什么这样就安全了" aria-label="Permalink to “为什么这样就安全了”">​</a></h3><ul><li><p><strong>短期有效</strong>：code 有效期只有几分钟，就算泄露，很快就会失效；</p></li><li><p><strong>一次性</strong>：用过立刻销毁，同一个 code 不能重复兑换；</p></li><li><p><strong>不暴露真实凭证</strong>：全程不会把 sessionId、JWT 这类长期凭证放在 URL 里；</p></li><li><p><strong>可校验来源</strong>：可以配合签名、白名单域名，确保 code 只能由可信系统发起。</p></li></ul><h2 id="四、补充说明" tabindex="-1">四、补充说明 <a class="header-anchor" href="#四、补充说明" aria-label="Permalink to “四、补充说明”">​</a></h2><ol><li><p><strong>和 JWT 跨域的共性</strong>：不管是传 sessionId 还是传 JWT，只要直接把长期登录凭证放在 URL 里，都有完全一样的安全问题。这也是为什么所有标准跨域登录方案，都一定会用授权码做一层中转。</p></li><li><p><strong>和标准 SSO 的关系</strong>：你的思路就是简化版的单点登录。完整的 CAS、OAuth2.0 就是在这个基础上，补齐了权限范围、多系统适配、统一登出、安全签名等标准化能力。</p></li><li><p><strong>适用场景</strong>：如果两个域名都是你们公司自有业务、共享后端存储，这套「共享 Redis + 授权码兑换」的方案足够轻量好用，不需要引入完整的 OAuth2 框架。</p></li></ol><p>需要我给你一份 Node.js 实现的「双域名授权码跨域登录」最小可运行代码示例吗？</p><blockquote><p>（注：部分内容可能由 AI 生成）</p></blockquote>',35)])])}const g=e(c,[["render",d]]);export{b as __pageData,g as default};
